"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$releaseFiles = Get-ChildItem '"'design\\releases\\0_2_0' -Filter '*.md' | Sort-Object Name
foreach ("'$releaseFile in $releaseFiles) {
  $content = Get-Content -Raw $releaseFile.FullName
  $title = [regex]::Match($content, '"'(?m)"'^title:'"\\s*(.+)"'$'"').Groups[1].Value.Trim()
  "'$bodyStart = $content.IndexOf("---", 3)
  $body = $content.Substring($bodyStart + 3)
  $summary = [regex]::Split($body, '"'(?im)"'^#{1,2}'"\\s+(Current state|implementation details|acceptance criteria)\\s*"'$'"')[0].Trim()
  [PSCustomObject]@{ File = "'$releaseFile.Name; Title = $title; Summary = $summary }
}'

